function [q] = latency(q_st, w, lat)
%LATENCY  A star-tracker attitude carried from t - lat to t with the gyro: q_st fromrotvec(w lat), unit.
%   q_st: real[1][4] (passed a plain number)
%   w: real[1][3] (passed a plain number)
%   lat: real[1] (passed a plain number)
%   returns q: real[1][4] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    q = zeros(4, 1);
    q = asils.alg.math.qnorm(asils.alg.math.qmult(q_st, asils.alg.math.fromrotvec((w * lat))));
end
